const raw = JSON.parse(document.querySelector("#library-data").textContent);
const actualRows = LibraryLab.normalizeRows(raw.rows);
console.assert(actualRows.every(r => typeof r.district === "string"),
  "정규화 결과가 district 계약을 지킵니다.");
const result = LibraryLab.searchLibraries(actualRows, "", "기흥구");
console.assert(result.length === 9, "고정 스냅샷의 예상 개수");
console.assert(result.every(r => r.address.includes("기흥구")),
  "소비자가 실제 기흥구 기록을 선택합니다.");

