import { test, expect } from "@playwright/test";
test("기흥구 필터", async ({ page }) => {
  await page.goto("/demo/");
  await page.getByLabel("지역", { exact: true }).selectOption("기흥구");
  const cards = page.locator("#library-results .library");
  await expect(cards).toHaveCount(9);
  await expect(cards.filter({ hasText: "경기도 용인시 기흥구" }))
    .toHaveCount(9);
  await expect(page.getByRole("heading", { name: "기흥도서관", exact: true }))
    .toBeVisible();
});

